mapper.select:
SELECT

FROM draw_resource_reservation
WHERE request_id = #{requestId}
  AND resource_type = #{resourceType}
  AND attempt_no = #{attemptNo}

mapper.update:
UPDATE draw_resource_reservation
SET status = 1,
    reserved_time = #{reservedTime},
    updated_time = #{reservedTime}
WHERE id = #{id}
  AND status = 0

mapper.select:
SELECT

FROM draw_resource_reservation
WHERE request_id = #{requestId}
  AND status IN (0, 1)
  AND (
      next_retry_time IS NULL
      OR next_retry_time <= #{now}
  )
ORDER BY resource_type, attempt_no, id

SELECT

FROM draw_resource_reservation
WHERE request_id = #{requestId}
  AND status = 3
  AND terminalized_time IS NULL
  AND (
      next_retry_time IS NULL
      OR next_retry_time <= #{now}
  )
ORDER BY resource_type, attempt_no, id
